1	export type Cell = [number, number];
2	
3	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	// Covers both survival (a live cell persisting) and birth (a dead cell with
17	// exactly 3 live neighbours coming alive) — hence "isAlive", not "survives".
18	const isAliveNextGeneration = (
19	  liveNeighbors: number,
20	  isCurrentlyAlive: boolean,
21	): boolean =>
22	  liveNeighbors === 3 || (liveNeighbors === 2 && isCurrentlyAlive);
23	
24	export function nextGeneration(cells: Cell[]): Cell[] {
25	  const livingKeys = new Set(cells.map(cellKey));
26	
27	  // Every live cell casts one vote for each of its 8 neighbors, so this tally
28	  // holds both the candidate cells and their live-neighbor counts in one pass.
29	  const tally = new Map<string, { cell: Cell; liveNeighbors: number }>();
30	  for (const cell of cells) {
31	    for (const neighbor of neighbors(cell)) {
32	      const key = cellKey(neighbor);
33	      const entry = tally.get(key) ?? { cell: neighbor, liveNeighbors: 0 };
34	      entry.liveNeighbors += 1;
35	      tally.set(key, entry);
36	    }
37	  }
38	
39	  const nextCells: Cell[] = [];
40	  for (const [key, { cell, liveNeighbors }] of tally) {
41	    if (isAliveNextGeneration(liveNeighbors, livingKeys.has(key))) {
42	      nextCells.push(cell);
43	    }
44	  }
45	
46	  return nextCells;
47	}
